        public _parser = (value: string | number | undefined | null) => {
             if (value) {
                const fetch = new Date();
                const values = String(value).split(':');
                if (values.length >= 2) {
                    const hour = Number(values[0]);
                    const minuts = Number(values[1]);
                    fetch.setHours(hour);
                    fetch.setMinutes(minuts);
                }
                fetch.setSeconds(0);
                return fetch.toString();
             }
            return;
         };
